}

@keyframes xt-soundwave {
    0%, 100% { transform: translateY(-50%) scaleY(1); }
    15%      { transform: translateY(-50%) scaleY(0.4); }
    30%      { transform: translateY(-50%) scaleY(1.5); }
    45%      { transform: translateY(-50%) scaleY(0.6); }
    60%      { transform: translateY(-50%) scaleY(1.3); }
    75%      { transform: translateY(-50%) scaleY(0.7); }
    90%      { transform: translateY(-50%) scaleY(1.1); }
}

#xt-t3:checked ~ .xt-content .xt-card:first-of-type .xt-text-lyric::after {
    animation: none !important;
    transform: translateY(-50%) scaleY(1) !important;
}

#xt-t3:checked ~ .xt-content .xt-card:first-of-type .xt-text-controls::after {
