:is(.xt-collapse, .xt-collapse-0, .xt-collapse-1, .xt-collapse-2):has(.xt-text-forumC1) .xt-text-forumR1,
:is(.xt-collapse, .xt-collapse-0, .xt-collapse-1, .xt-collapse-2):has(.xt-text-forumC1) .xt-text-forumR2 {
    display: block;
    margin: 0 !important;
    padding: 3px 14px 0 38px !important;
