:is(.xt-collapse, .xt-collapse-0, .xt-collapse-1, .xt-collapse-2):has(.xt-text-forumC1) .xt-divider::before, :is(.xt-collapse, .xt-collapse-0, .xt-collapse-1, .xt-collapse-2):has(.xt-text-forumC1) .xt-divider::after { content: none !important; display: none !important; }
/* 底部输入框：纯文字占位 */
:is(.xt-collapse, .xt-collapse-0, .xt-collapse-1, .xt-collapse-2):has(.xt-text-forumC1) .xt-collapse-body::after {
    content: "\B313\AE00\C744  \B0A8\AC8C\BCF4\C138\C694.";
    display: block;
    box-sizing: border-box;
