@endcard

@collapse "댓글 6" 0
  @text forumN1
  @text forumC1
  @text forumRN1
  @text forumR1
  @divider
  @text forumN2
  @text forumC2
  @divider
  @text forumN3
  @text forumC3
  @text forumRN2
  @text forumR2
  @divider
  @text forumN4
  @text forumC4
@endcollapse

@spacer 14

# ===== 小剧场：Char 和 user 的平行世界（每句台词前有署名，旁白穿插） =====
@card
  @text theaterTitle
  @text theaterWorld
  @text theaterScene
  @text theaterS1
  @text theaterL1
  @text theaterS2
  @text theaterL2
  @text theaterN2
  @text theaterS3
  @text theaterL3
  @text theaterS4
  @text theaterL4
  @text theaterN3
  @text theaterS5
  @text theaterL5
  @text theaterS6
  @text theaterL6
  @text theaterEnd
@endcard

@spacer 12

@section MY REVIEW
  review

xinshengCustomCss:
/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ ================= 0. 感谢@薄荷猫宝宝的字体 ================= */
/* 🌟 修复：这里绝对不能加 !important，否则会失效 */
@font-face {
    font-family: 'MasterFont';
    src: url('https://nos.netease.com/ysf/b7a4e983b18dedf08063532c00575aeb.ttf') format('truetype');
}

/* ================= 1. 重置与容器 ================= */
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { margin: 0 !important; border: none !important; display: block !important; box-shadow: none !important; white-space: pre-wrap !important; outline: none !important; background: transparent !important; }
.xt-root::-webkit-scrollbar, .xt-text::-webkit-scrollbar { display: none !important; width: 0 !important; }

/* 根容器：全透明 */
.xt-root {
    width: 360px !important; 
    height: 700px !important; 
    overflow: hidden !important;
    background-color: transparent !important; 
    background-image: none !important;
    box-shadow: none !important;
    position: relative !important; 
    margin: 20px auto !important;
    display: block !important; 
}

/* 便利贴通用样式 */
.xt-text:nth-of-type(-n+4) {
    position: absolute !important;
    background-color: transparent !important;
    color: #333333 !important;
    font-size: 14px !important;
    line-height: 1.6 !important;
    z-index: 10 !important;
    word-break: break-word !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    box-shadow: none !important;

    /* 🌟 核心：使用@薄荷猫专属字体 */
    font-family: 'MasterFont', sans-serif !important;
