}

/* 夜间模式卡片深色 */
#xt-t5:checked ~ .xt-content .xt-card:first-of-type {
    background-color: #1a1a2e !important;
}

#xt-t5:checked ~ .xt-content .xt-card:first-of-type .xt-text-songTitle {
