    font-weight: 400 !important;
    color: var(--letter-ink) !important;
    line-height: 1.85 !important;
    letter-spacing: 0.8px !important;
    text-align: justify !important;
    background: transparent !important;
    padding: 0 !important;
    margin: 0 0 20px 0 !important;
