    font-style: normal !important;
}
.xt-divider {
    border: none !important;
    border-top: 1px solid var(--t-line) !important;
    background: none !important;
    height: 0 !important;
    margin: 0;
}

/* ===== 数据行：图标（用 mask 画，跟随文字颜色） ===== */
.xt-grid {
