/* ===== 自己的补充评论：左头像 + 右内容 + 串联线 ===== */
.xt-card {
    position: relative;
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    background: transparent !important;
    backdrop-filter: none !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    margin: 0 !important;
    padding: 12px 8px 12px 62px !important;
}
.xt-card-title { display: none; }
.xt-card .xt-image {
    position: absolute;
    left: 2px;
    top: 12px;
    width: 44px;
    height: 44px;
    margin: 0;
    z-index: 1;
}
.xt-card .xt-image img {
    width: 44px;
    height: 44px;
    border-radius: 50%;
    object-fit: cover;
    display: block;
}
.xt-card .xt-text-charName {
    flex: 0 0 auto;
    background: none !important;
    padding: 0 6px 0 0 !important;
    font-size: 16px;
    font-weight: 800;
    color: var(--t-text) !important;
    font-style: normal !important;
}
.xt-card .xt-text-c1meta,
.xt-card .xt-text-c2meta,
.xt-card .xt-text-c3meta {
    flex: 1 1 0;
    min-width: 0;
    background: none !important;
    padding: 0 !important;
    font-size: 14px;
    color: var(--t-sub) !important;
    font-style: normal !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.xt-card .xt-text-c1text,
.xt-card .xt-text-c2text,
.xt-card .xt-text-c3text {
    flex: 0 0 100%;
    background: none !important;
    padding: 2px 0 0 !important;
    font-size: 16px;
    line-height: 1.5;
    color: var(--t-text) !important;
    font-style: normal !important;
}
/* 串联线：头像下方连到下一条 */
.xt-card::after {
    content: "";
    position: absolute;
    left: 23px;
    top: 60px;
    bottom: 0;
    width: 2px;
    background: var(--t-thread);
}
.xt-card:last-child::after { display: none; }
/* 头像上方的小接头（第一条不要） */
.xt-card::before {
    content: "";
    position: absolute;
    left: 23px;
    top: 0;
    height: 10px;
    width: 2px;
    background: var(--t-thread);
}
.xt-divider + .xt-card::before { display: none; }

