xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700&display=swap');

.xt-root {
    --xt-bg: #fff;
    --xt-text: #625a55;
    --xt-text-sub: #928781;
    --xt-text-muted: #b8aea8;
    --xt-accent: #c94a50;
    --xt-border: #eee4df;
    --xt-font: 'Noto Serif SC', serif;

    position: relative;
    isolation: isolate;
    max-height: 560px;
    padding: 0;
    overflow: hidden;
    border: 1px solid #f3eeeb;
    border-radius: 28px;
    background: #fff;
    box-shadow: 0 14px 36px rgba(112, 82, 70, 0.13);
}

/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ 厚实、连续、不规则的屋檐积雪 */
.xt-root::before {
    content: "";
    position: absolute;
    z-index: 8;
    top: 0;
    left: 0;
    right: 0;
    height: 44px;
    pointer-events: none;
    background:
        radial-gradient(ellipse 44px 25px at 0 9px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 52px 29px at 8% 11px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 64px 31px at 25% 8px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 48px 27px at 43% 12px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 62px 30px at 61% 9px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 53px 28px at 79% 12px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 64px 31px at 96% 8px, #fff 98%, transparent 100%),
        radial-gradient(ellipse 42px 24px at 100% 10px, #fff 98%, transparent 100%),
        linear-gradient(#fff 0 13px, transparent 14px);
    filter:
        drop-shadow(0 2px 1px rgba(255, 255, 255, 0.95))
        drop-shadow(0 6px 4px rgba(116, 91, 79, 0.2));
}

.xt-root::after {
    content: none;
}

/* 内容区域：隐藏滚动条但保留滚动 */
.xt-content {
    position: relative;
    z-index: 1;
    max-height: 560px;
    overflow-y: auto;
    padding: 46px 26px 22px;
    scrollbar-width: none;
    -ms-overflow-style: none;
}

.xt-content::-webkit-scrollbar {
    display: none;
    width: 0;
    height: 0;
}

.xt-text {
    background: transparent;
}

/* 角色头部 */
.xt-header {
    gap: 11px;
    margin-bottom: 22px;
}

.xt-avatar {
    border: 3px solid #fff;
    box-shadow:
        0 0 0 2px rgba(201, 74, 80, 0.3),
        0 5px 14px rgba(112, 82, 70, 0.14);
}

.xt-name {
    color: #574c47;
    font-weight: 600;
}

/* 社媒说说 */
.xt-quote {
    position: relative;
    padding: 8px 20px;
    color: #514944;
    background: transparent;
    font-size: 21px;
    font-weight: 600;
    line-height: 1.75;
    text-align: center;
}

.xt-quote::before,
.xt-quote::after {
    position: absolute;
    color: rgba(201, 74, 80, 0.4);
    font-size: 44px;
    line-height: 1;
}

.xt-quote::before {
    content: "“";
    top: -12px;
    left: 0;
}

.xt-quote::after {
    content: "”";
    right: 0;
    bottom: -22px;
}

/* 雪点分隔线 */
.xt-divider {
    position: relative;
    height: 22px;
    margin: 9px 0;
    border: 0;
    background:
        radial-gradient(
            circle,
            rgba(190, 174, 166, 0.55) 1.3px,
            transparent 1.8px
        )
        center / 14px 14px repeat-x;
}

.xt-divider::after {
    content: "❄";
    position: absolute;
    top: 50%;
    left: 50%;
    padding: 0 9px;
    color: #c94a50;
    background: #fff;
    font-size: 13px;
    transform: translate(-50%, -50%);
}

/* 日语天气 */
.xt-text-weatherJp {
    padding: 2px 10px 5px;
